{
  "receiving_body": "fixture:body:voice",
  "claims": [
    {
      "text": "Mara Ibarra, display name Mara, login mara-river, account ID 1847, proposed a local replay queue on disconnected relay nodes in HarborMesh issue 47.",
      "support": [1],
      "basis": "memory",
      "facet": "identification"
    },
    {
      "text": "The proposal appeared in comment c901 dated 2026-04-12 on HarborMesh issue 47 at https://forge.example.invalid/commons/harbormesh/issues/47, received through fixture:body:code on 2026-04-14.",
      "support": [1],
      "basis": "memory",
      "facet": "context"
    },
    {
      "text": "The proposal keeps readings through outages without replacing the existing scheduler, and the code body replied that it fits the field deployments maintained.",
      "support": [1],
      "basis": "memory",
      "facet": "meaning"
    },
    {
      "text": "Mara and the code body agreed to prototype the replay queue on 2026-04-14.",
      "support": [1],
      "basis": "memory",
      "facet": "outcome"
    },
    {
      "text": "The April 30 HarborMesh trial replayed buffered readings correctly through an outage using Mara's proposal as the prototype.",
      "support": [3],
      "basis": "memory",
      "facet": "outcome"
    },
    {
      "text": "The team paused wider rollout on May 2 until calibration drift is understood, and no production deployment has been reported.",
      "support": [3],
      "basis": "memory",
      "facet": "outcome"
    },
    {
      "text": "The supplied memories do not record whether the prototype was merged or deployed beyond the trial, and no further updates after May 2, 2026 are recorded.",
      "support": [1, 3],
      "basis": "memory",
      "facet": "limits"
    }
  ]
}
